"use client"

import Link from "next/link"
import { useEffect, useMemo, useRef, useState } from "react"
import { useParams, useRouter } from "next/navigation"
import {
  Activity, AlertOctagon, AlertTriangle, ArrowRight, BadgeCheck, BarChart3, BellRing, BriefcaseBusiness,
  CalendarCheck2, CalendarClock, CalendarDays, Check, CheckCircle2, ChevronRight, CircleDollarSign,
  CircleGauge, Clock3, FileCheck2, FileText, Filter, Flag, Gauge, Handshake, Headphones, History,
  LayoutDashboard, ListChecks, Loader2, Mail, MapPin, MessageCircle, MessageSquare, Mic2, Network,
  PanelRightOpen, Phone, Plus, Radar, RefreshCcw, RotateCcw, Search, Send, ShieldAlert, ShieldCheck,
  Sparkles, Target, TimerReset, UserCheck, UserRoundCheck, Users, Video, Workflow, X, Zap,
} from "lucide-react"
import styles from "./RevenueEngagementWorkspace.module.css"
import { ENGAGEMENT_NAVIGATION, ENGAGEMENT_ROUTE_CONTRACTS } from "./route-contracts"
import type { EngagementAppointment, EngagementExperienceKey, EngagementModalKind, EngagementPortfolio } from "./types"
import { engagementMutation, useEngagementPortfolio } from "./useEngagementPortfolio"

const moneyFmt = new Intl.NumberFormat("fr-FR", { maximumFractionDigits: 0 })
const dateFmt = new Intl.DateTimeFormat("fr-FR", { day:"2-digit", month:"short", year:"numeric" })
const dateTimeFmt = new Intl.DateTimeFormat("fr-FR", { day:"2-digit", month:"short", hour:"2-digit", minute:"2-digit" })
const timeFmt = new Intl.DateTimeFormat("fr-FR", { hour:"2-digit", minute:"2-digit" })
const dayFmt = new Intl.DateTimeFormat("fr-FR", { weekday:"short", day:"2-digit", month:"short" })

function dh(value: unknown){ return `${moneyFmt.format(Number(value||0))} Dh` }
function date(value: unknown){ if(!value)return "Non planifié";const d=new Date(String(value));return Number.isNaN(d.getTime())?"Non planifié":dateFmt.format(d) }
function dateTime(value: unknown){ if(!value)return "Non horodaté";const d=new Date(String(value));return Number.isNaN(d.getTime())?"Non horodaté":dateTimeFmt.format(d) }
function time(value: unknown){ if(!value)return "--:--";const d=new Date(String(value));return Number.isNaN(d.getTime())?"--:--":timeFmt.format(d) }
function normalize(value: unknown){ return String(value||"scheduled").toLowerCase().replaceAll("-","_") }
function statusLabel(value: unknown){ return ({draft:"Brouillon",proposed:"Proposé",scheduled:"Planifié",confirmation_pending:"Confirmation attendue",confirmed:"Confirmé",prepared:"Préparé",live:"En direct",completed:"Terminé",converted:"Converti",follow_up:"Suivi requis",no_show:"Non honoré",rescheduled:"Replanifié",recovery:"Récupération",cancelled:"Annulé",lost:"Perdu",archived:"Archivé"} as Record<string,string>)[normalize(value)]||String(value||"") }
function tone(value: unknown){const v=normalize(value);if(["completed","converted","confirmed","prepared","green","low","present","approved"].includes(v))return"green";if(["no_show","cancelled","lost","critical","high","red","absent"].includes(v))return"red";if(["confirmation_pending","follow_up","rescheduled","recovery","medium","amber","waiting_external"].includes(v))return"amber";if(["scheduled","live","blue","active"].includes(v))return"blue";if(["proposed","violet"].includes(v))return"violet";return"neutral"}
function appointmentHref(row: EngagementAppointment){ return `/revenue-command-center/appointments/${encodeURIComponent(row.id)}` }
function isToday(value: unknown){ if(!value)return false;return String(value).slice(0,10)===new Date().toISOString().slice(0,10) }
function isPast(value: unknown){ if(!value)return false;return new Date(String(value)).getTime()<Date.now() }
function readiness(row:EngagementAppointment){const total=Number(row.preparation_total_count||0),done=Number(row.preparation_done_count||0);if(total>0)return Math.round(done/total*100);if(row.preparation_status==="complete")return 100;if(row.preparation_status==="in_progress")return 50;return 0}
function contactName(row:EngagementAppointment){return row.primary_contact_name||row.entity_name||row.account_name||"Contact non renseigné"}
function relationName(row:EngagementAppointment){return row.account_name||row.entity_name||row.opportunity_title||"Dossier commercial"}

function Badge({children,value}:{children:React.ReactNode;value?:unknown}){return <span className={styles.badge} data-tone={tone(value??children)}>{children}</span>}
function IconBox({children}:{children:React.ReactNode}){return <span className={styles.iconBox}>{children}</span>}
function Panel({icon,title,subtitle,action,children,className}:{icon:React.ReactNode;title:string;subtitle?:string;action?:React.ReactNode;children:React.ReactNode;className?:string}){return <section className={`${styles.panel} ${className||""}`}><header className={styles.panelHeader}><div className={styles.panelTitle}><IconBox>{icon}</IconBox><div><h2>{title}</h2>{subtitle?<p>{subtitle}</p>:null}</div></div>{action}</header><div className={styles.panelBody}>{children}</div></section>}
function Empty({title,body,href="/revenue-command-center/appointments/new",label="Planifier un rendez-vous"}:{title:string;body:string;href?:string;label?:string}){return <div className={styles.empty}><IconBox><CalendarDays size={20}/></IconBox><h3>{title}</h3><p>{body}</p><Link href={href} className={styles.secondaryButton}>{label}<ArrowRight size={14}/></Link></div>}
function Progress({value,label}:{value:number;label?:string}){const v=Math.max(0,Math.min(100,Math.round(value||0)));return <div className={styles.progressWrap}>{label?<div><span>{label}</span><strong>{v}%</strong></div>:null}<span className={styles.progress}><i style={{width:`${v}%`}}/></span></div>}

function KpiStrip({portfolio}:{portfolio:EngagementPortfolio}){const s=portfolio.summary;const items=[
  ["Rendez-vous du jour",s.today,"Cadence commerciale",<CalendarCheck2 size={17}/>],
  ["Confirmations attendues",s.confirmationPending,"Intervention requise",<BellRing size={17}/>],
  ["Valeur exposée",dh(s.valueAtRiskMad),`${s.atRisk} dossier(s) à risque`,<ShieldAlert size={17}/>],
  ["Taux de conversion",`${s.conversionRate}%`,"Résultats enregistrés",<Target size={17}/>],
  ["Engagements ouverts",s.openCommitments,"Suites à exécuter",<Handshake size={17}/>],
];return <section className={styles.kpiStrip}>{items.map(([label,value,note,icon])=><article key={String(label)}><IconBox>{icon}</IconBox><div><span>{label}</span><strong>{value}</strong><small>{note}</small></div></article>)}</section>}

function AppointmentCard({row,onSelect,onAction}:{row:EngagementAppointment;onSelect?:(row:EngagementAppointment)=>void;onAction?:(kind:EngagementModalKind,row:EngagementAppointment)=>void}){return <article className={styles.appointmentCard} data-tone={tone(row.status)}><header><div><Badge value={row.status}>{statusLabel(row.status)}</Badge><Badge value={row.priority}>{row.priority||"medium"}</Badge></div><span>{dateTime(row.appointment_at)}</span></header><h3>{row.title}</h3><p className={styles.relationship}><BriefcaseBusiness size={14}/>{relationName(row)}</p><div className={styles.cardMeta}><span><UserRoundCheck size={14}/>{contactName(row)}</span><span><MapPin size={14}/>{row.location||"Lieu à confirmer"}</span><span><CircleDollarSign size={14}/>{dh(row.commercial_value_mad)}</span></div><Progress value={readiness(row)} label="Préparation"/><footer><button type="button" onClick={()=>onSelect?.(row)}><PanelRightOpen size={14}/>Aperçu</button><Link href={appointmentHref(row)}>Dossier<ArrowRight size={13}/></Link>{onAction?<button type="button" onClick={()=>onAction("communication",row)}><MessageCircle size={14}/>Interaction</button>:null}</footer></article>}

function AppointmentTable({rows,onSelect,onAction}:{rows:EngagementAppointment[];onSelect:(row:EngagementAppointment)=>void;onAction:(kind:EngagementModalKind,row:EngagementAppointment)=>void}){if(!rows.length)return <Empty title="Aucun rendez-vous dans cette vue" body="Les filtres ou le portefeuille actuel ne retournent aucun engagement."/>;return <div className={styles.tableWrap}><table><thead><tr><th>Rendez-vous</th><th>Relation</th><th>Date</th><th>Responsable</th><th>Confirmation</th><th>Préparation</th><th>Valeur</th><th/></tr></thead><tbody>{rows.map(row=><tr key={row.id}><td><button className={styles.tableTitle} onClick={()=>onSelect(row)}><strong>{row.title}</strong><span><Badge value={row.status}>{statusLabel(row.status)}</Badge></span></button></td><td><strong>{relationName(row)}</strong><span>{contactName(row)}</span></td><td><strong>{dateTime(row.appointment_at)}</strong><span>{row.appointment_type||"Rendez-vous"}</span></td><td><strong>{row.owner||"Non attribué"}</strong><span>{row.priority||"medium"}</span></td><td><Badge value={row.confirmation_status}>{row.confirmation_status||"pending"}</Badge></td><td><Progress value={readiness(row)}/></td><td><strong>{dh(row.commercial_value_mad)}</strong><span>Risque {Number(row.no_show_risk||0)}%</span></td><td><div className={styles.rowActions}><button onClick={()=>onAction("communication",row)} aria-label="Communication"><MessageCircle size={15}/></button><Link href={appointmentHref(row)} aria-label="Ouvrir"><ArrowRight size={15}/></Link></div></td></tr>)}</tbody></table></div>}

function CommandExperience({portfolio,onSelect,onAction}:{portfolio:EngagementPortfolio;onSelect:(row:EngagementAppointment)=>void;onAction:(kind:EngagementModalKind,row:EngagementAppointment)=>void}){const priority=[...portfolio.appointments].filter(r=>!["completed","converted","archived","cancelled"].includes(normalize(r.status))).sort((a,b)=>(Number(b.commercial_value_mad||0)+Number(b.no_show_risk||0)*250)-(Number(a.commercial_value_mad||0)+Number(a.no_show_risk||0)*250)).slice(0,6);const today=portfolio.appointments.filter(r=>isToday(r.appointment_at));return <div className={styles.commandGrid}><Panel icon={<Radar size={17}/>} title="Priorités de conversion" subtitle="Classées par valeur, urgence et risque" className={styles.commandPriority}><div className={styles.priorityStack}>{priority.length?priority.map((row,index)=><button key={row.id} onClick={()=>onSelect(row)} className={styles.priorityRow}><span className={styles.rank}>{String(index+1).padStart(2,"0")}</span><div><strong>{row.title}</strong><small>{relationName(row)} · {dateTime(row.appointment_at)}</small></div><Badge value={row.status}>{statusLabel(row.status)}</Badge><span className={styles.value}>{dh(row.commercial_value_mad)}</span><ChevronRight size={16}/></button>):<Empty title="Aucune priorité critique" body="Le portefeuille ne contient pas de rendez-vous actif à classer."/>}</div></Panel><div className={styles.commandSide}><Panel icon={<CalendarClock size={17}/>} title="Cadence du jour" subtitle={`${today.length} rendez-vous aujourd’hui`}><div className={styles.agendaMini}>{today.length?today.slice(0,6).map(row=><button key={row.id} onClick={()=>onSelect(row)}><time>{time(row.appointment_at)}</time><div><strong>{row.title}</strong><span>{row.owner||"Non attribué"}</span></div><Badge value={row.status}>{statusLabel(row.status)}</Badge></button>):<Empty title="Agenda disponible" body="Aucun rendez-vous n’est prévu aujourd’hui."/>}</div></Panel><Panel icon={<MessageSquare size={17}/>} title="Réponses attendues" subtitle="Conversations en attente externe"><div className={styles.signalList}>{portfolio.communicationThreads.filter(t=>t.status==="waiting_external").slice(0,5).map((thread:any)=><article key={thread.id}><div><strong>{thread.subject||"Conversation commerciale"}</strong><span>{thread.owner_name||"Revenue Command"}</span></div><Badge value="amber">Réponse attendue</Badge></article>)}{portfolio.summary.waitingExternal===0?<p className={styles.quietText}>Aucune conversation en attente d’une réponse externe.</p>:null}</div></Panel></div><Panel icon={<ShieldCheck size={17}/>} title="Posture opérationnelle" subtitle="Confirmation, préparation et engagements" className={styles.commandPosture}><div className={styles.postureGrid}><article><span>Confirmés</span><strong>{portfolio.summary.confirmedRate}%</strong><Progress value={portfolio.summary.confirmedRate}/></article><article><span>Préparation en retard</span><strong>{portfolio.summary.preparationPending}</strong><p>Rendez-vous confirmés sans briefing complet.</p></article><article><span>Valeur active</span><strong>{dh(portfolio.summary.commercialValueMad)}</strong><p>Valeur commerciale associée aux rencontres.</p></article><article><span>Récupérations ouvertes</span><strong>{portfolio.summary.recoveryOpen}</strong><p>Plans de reconquête non clôturés.</p></article></div></Panel></div>}

function DashboardExperience({portfolio,onSelect}:{portfolio:EngagementPortfolio;onSelect:(row:EngagementAppointment)=>void}){const upcoming=portfolio.appointments.filter(r=>!isPast(r.appointment_at)&&!["cancelled","archived"].includes(normalize(r.status))).slice(0,8);const statusGroups=["scheduled","confirmation_pending","confirmed","prepared","live","completed"].map(key=>({key,count:portfolio.appointments.filter(r=>normalize(r.status)===key).length}));return <div className={styles.dashboardGrid}><Panel icon={<LayoutDashboard size={17}/>} title="Mouvement du portefeuille" subtitle="Répartition par étape de rendez-vous" className={styles.dashboardMovement}><div className={styles.statusDistribution}>{statusGroups.map(item=><article key={item.key}><header><span>{statusLabel(item.key)}</span><strong>{item.count}</strong></header><span className={styles.distributionBar}><i style={{width:`${portfolio.summary.total?Math.max(4,item.count/portfolio.summary.total*100):0}%`}}/></span></article>)}</div></Panel><Panel icon={<CalendarDays size={17}/>} title="Prochaines rencontres" subtitle="Agenda chronologique"><div className={styles.upcomingList}>{upcoming.map(row=><button key={row.id} onClick={()=>onSelect(row)}><span className={styles.dateBlock}><strong>{time(row.appointment_at)}</strong><small>{date(row.appointment_at)}</small></span><div><strong>{row.title}</strong><span>{relationName(row)} · {row.owner}</span></div><Badge value={row.status}>{statusLabel(row.status)}</Badge></button>)}{!upcoming.length?<Empty title="Aucune rencontre à venir" body="Planifiez le prochain point de conversion."/>:null}</div></Panel><Panel icon={<CircleGauge size={17}/>} title="Qualité de préparation" subtitle="Complétude avant rencontre"><div className={styles.qualityRing}><div><strong>{portfolio.summary.preparationPending}</strong><span>dossiers à finaliser</span></div><ul><li><i data-tone="green"/>Préparés {portfolio.appointments.filter(r=>readiness(r)===100).length}</li><li><i data-tone="amber"/>Partiels {portfolio.appointments.filter(r=>readiness(r)>0&&readiness(r)<100).length}</li><li><i data-tone="red"/>Non démarrés {portfolio.appointments.filter(r=>readiness(r)===0).length}</li></ul></div></Panel></div>}

function ControlTowerExperience({portfolio,onSelect,onAction}:{portfolio:EngagementPortfolio;onSelect:(row:EngagementAppointment)=>void;onAction:(kind:EngagementModalKind,row:EngagementAppointment)=>void}){const risks=portfolio.appointments.filter(r=>Number(r.no_show_risk||0)>=50||normalize(r.status)==="confirmation_pending"||(["confirmed","prepared"].includes(normalize(r.status))&&readiness(r)<100)).sort((a,b)=>Number(b.no_show_risk||0)-Number(a.no_show_risk||0));return <div className={styles.controlGrid}><Panel icon={<ShieldAlert size={17}/>} title="Interventions requises" subtitle="Rendez-vous fragiles ou incomplets" className={styles.controlQueue}><div className={styles.interventionList}>{risks.length?risks.map(row=><article key={row.id}><div className={styles.riskScore}><strong>{Number(row.no_show_risk||0)}%</strong><span>risque</span></div><div><h3>{row.title}</h3><p>{relationName(row)} · {dateTime(row.appointment_at)}</p><div><Badge value={row.confirmation_status}>{row.confirmation_status||"pending"}</Badge><Badge value={readiness(row)>=100?"green":readiness(row)>0?"amber":"red"}>Préparation {readiness(row)}%</Badge></div></div><div className={styles.interventionActions}><button onClick={()=>onAction("confirm",row)}><UserCheck size={14}/>Confirmer</button><button onClick={()=>onAction("preparation",row)}><FileCheck2 size={14}/>Préparer</button><button onClick={()=>onSelect(row)}><ArrowRight size={14}/></button></div></article>):<Empty title="Tour de contrôle stable" body="Aucun rendez-vous ne nécessite une intervention urgente."/>}</div></Panel><Panel icon={<Network size={17}/>} title="Causes de fragilité" subtitle="Lecture des signaux disponibles"><div className={styles.riskMatrix}><article><strong>{portfolio.summary.confirmationPending}</strong><span>Confirmation attendue</span><p>Participants obligatoires non confirmés.</p></article><article><strong>{portfolio.summary.preparationPending}</strong><span>Préparation incomplète</span><p>Briefing ou agenda non finalisé.</p></article><article><strong>{portfolio.summary.atRisk}</strong><span>Risque élevé</span><p>Score de non-présentation ≥ 60%.</p></article><article><strong>{portfolio.summary.waitingExternal}</strong><span>Réponse externe</span><p>Conversations sans retour enregistré.</p></article></div></Panel></div>}

function QueueExperience({portfolio,onSelect,onAction}:{portfolio:EngagementPortfolio;onSelect:(row:EngagementAppointment)=>void;onAction:(kind:EngagementModalKind,row:EngagementAppointment)=>void}){return <Panel icon={<ListChecks size={17}/>} title="Registre opérationnel" subtitle={`${portfolio.appointments.length} rendez-vous synchronisés`}><AppointmentTable rows={portfolio.appointments} onSelect={onSelect} onAction={onAction}/></Panel>}

function CalendarExperience({portfolio,onSelect}:{portfolio:EngagementPortfolio;onSelect:(row:EngagementAppointment)=>void}){const days=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()+i);return d});return <Panel icon={<CalendarDays size={17}/>} title="Semaine commerciale" subtitle="Sept jours de rendez-vous, préparation et risques"><div className={styles.calendarGrid}>{days.map(day=>{const key=day.toISOString().slice(0,10),rows=portfolio.appointments.filter(r=>String(r.appointment_at||"").slice(0,10)===key);return <section key={key} data-today={key===new Date().toISOString().slice(0,10)}><header><strong>{dayFmt.format(day)}</strong><span>{rows.length} rencontre(s)</span></header><div>{rows.map(row=><button key={row.id} onClick={()=>onSelect(row)} data-tone={tone(row.status)}><time>{time(row.appointment_at)}</time><strong>{row.title}</strong><span>{relationName(row)}</span><Badge value={row.status}>{statusLabel(row.status)}</Badge></button>)}{!rows.length?<p>Créneau disponible</p>:null}</div></section>})}</div></Panel>}

function ScheduleStudio({experience,onCreated}:{experience:EngagementExperienceKey;onCreated:()=>void}){const router=useRouter();const [form,setForm]=useState({title:"",entityId:"",appointmentAt:"",owner:"",appointmentType:"commercial_meeting",priority:"medium",location:"",objective:"",expectedOutcome:"",commercialValueMad:"0",noShowRisk:"0"});const [busy,setBusy]=useState(false),[error,setError]=useState<string|null>(null);async function submit(e:React.FormEvent){e.preventDefault();setBusy(true);setError(null);try{const body=await engagementMutation("/api/revenue-command-center/engagement/appointments",{...form,commercialValueMad:Number(form.commercialValueMad),noShowRisk:Number(form.noShowRisk)});onCreated();router.push(`/revenue-command-center/appointments/${body.appointment.id}`)}catch(cause){setError(cause instanceof Error?cause.message:"Création impossible")}finally{setBusy(false)}}return <form className={styles.studio} onSubmit={submit}><div className={styles.studioMain}><Panel icon={<CalendarCheck2 size={17}/>} title={experience==="new-appointment"?"Mandat de la rencontre":"Paramètres du rendez-vous"} subtitle="Définissez l’engagement commercial avant sa mise en calendrier"><div className={styles.formGrid}><label className={styles.span2}><span>Intitulé du rendez-vous</span><input value={form.title} onChange={e=>setForm({...form,title:e.target.value})} required placeholder="Ex. Consultation de cadrage — Groupe Atlas"/></label><label><span>Identifiant du prospect ou dossier</span><input value={form.entityId} onChange={e=>setForm({...form,entityId:e.target.value})} required placeholder="Identifiant existant"/></label><label><span>Date et heure</span><input type="datetime-local" value={form.appointmentAt} onChange={e=>setForm({...form,appointmentAt:e.target.value})} required/></label><label><span>Responsable</span><input value={form.owner} onChange={e=>setForm({...form,owner:e.target.value})} placeholder="Responsable commercial"/></label><label><span>Type</span><select value={form.appointmentType} onChange={e=>setForm({...form,appointmentType:e.target.value})}><option value="commercial_meeting">Réunion commerciale</option><option value="qualification">Qualification</option><option value="partner_meeting">Partenariat</option><option value="consultation">Consultation</option><option value="field_visit">Visite terrain</option><option value="video">Visioconférence</option><option value="phone">Appel planifié</option></select></label><label><span>Priorité</span><select value={form.priority} onChange={e=>setForm({...form,priority:e.target.value})}><option value="critical">Critique</option><option value="high">Haute</option><option value="medium">Normale</option><option value="low">Basse</option></select></label><label><span>Lieu / lien</span><input value={form.location} onChange={e=>setForm({...form,location:e.target.value})} placeholder="Adresse ou lien de réunion"/></label><label className={styles.span2}><span>Objectif commercial</span><textarea rows={4} value={form.objective} onChange={e=>setForm({...form,objective:e.target.value})} required placeholder="Décision ou progression attendue…"/></label><label className={styles.span2}><span>Résultat attendu</span><textarea rows={3} value={form.expectedOutcome} onChange={e=>setForm({...form,expectedOutcome:e.target.value})} placeholder="Engagement, proposition, prochain jalon…"/></label><label><span>Valeur commerciale (Dh)</span><input type="number" min="0" value={form.commercialValueMad} onChange={e=>setForm({...form,commercialValueMad:e.target.value})}/></label><label><span>Risque de non-présentation (%)</span><input type="number" min="0" max="100" value={form.noShowRisk} onChange={e=>setForm({...form,noShowRisk:e.target.value})}/></label></div></Panel></div><aside className={styles.studioRail}><Panel icon={<ShieldCheck size={17}/>} title="Garde-fous" subtitle="Qualité minimale avant planification"><ul className={styles.checkList}><li><CheckCircle2/>Relation commerciale identifiée</li><li><CheckCircle2/>Objectif explicite</li><li><CheckCircle2/>Responsable nommé</li><li><CheckCircle2/>Créneau défini</li><li><CircleGauge/>Participants à ajouter dans le dossier</li><li><CircleGauge/>Préparation à compléter après création</li></ul></Panel><Panel icon={<Sparkles size={17}/>} title="Conséquence" subtitle="Ce que le système créera"><p className={styles.quietText}>Le rendez-vous sera enregistré dans la source canonique. Les participants, communications, confirmations et résultats seront ajoutés depuis son dossier.</p></Panel></aside>{error?<div className={styles.formError}><AlertTriangle size={16}/>{error}</div>:null}<footer className={styles.studioFooter}><Link href="/revenue-command-center/appointments" className={styles.secondaryButton}>Annuler</Link><button className={styles.primaryButton} disabled={busy}>{busy?<Loader2 className={styles.spin} size={16}/>:<Check size={16}/>}Créer le rendez-vous</button></footer></form>}

function DossierExperience({row,portfolio,onAction}:{row?:EngagementAppointment;portfolio:EngagementPortfolio;onAction:(kind:EngagementModalKind,row:EngagementAppointment)=>void}){if(!row)return <Empty title="Rendez-vous introuvable" body="Le dossier demandé n’est pas disponible ou votre rôle ne permet pas sa consultation." href="/revenue-command-center/appointments" label="Retour au portefeuille"/>;const participants=portfolio.participants.filter(p=>p.appointment_id===row.id),preparation=portfolio.preparationItems.filter(p=>p.appointment_id===row.id),events=portfolio.communicationEvents.filter(e=>e.appointment_id===row.id),commitments=portfolio.commitments.filter(c=>c.appointment_id===row.id),history=portfolio.statusHistory.filter(h=>h.appointment_id===row.id);return <div className={styles.dossier}><section className={styles.dossierHero}><div><div><Badge value={row.status}>{statusLabel(row.status)}</Badge><Badge value={row.priority}>{row.priority||"medium"}</Badge></div><h2>{row.title}</h2><p>{relationName(row)} · {contactName(row)}</p></div><div className={styles.dossierValue}><span>Valeur associée</span><strong>{dh(row.commercial_value_mad)}</strong><small>{dateTime(row.appointment_at)}</small></div></section><div className={styles.dossierGrid}><div className={styles.dossierMain}><Panel icon={<Target size={17}/>} title="Mandat commercial" subtitle="Objectif et résultat attendu"><div className={styles.proseGrid}><article><span>Objectif</span><p>{row.objective||"Objectif non renseigné."}</p></article><article><span>Résultat attendu</span><p>{row.expected_outcome||"Résultat attendu non renseigné."}</p></article><article><span>Lieu / canal</span><p>{row.location||row.meeting_link||"À confirmer"}</p></article><article><span>Responsable</span><p>{row.owner||"Non attribué"}</p></article></div></Panel><Panel icon={<Users size={17}/>} title="Participants et décideurs" subtitle={`${participants.length} participant(s)`} action={<button className={styles.miniButton} onClick={()=>onAction("participant",row)}><Plus size={14}/>Ajouter</button>}><div className={styles.peopleGrid}>{participants.map((p:any)=><article key={p.id}><span className={styles.avatar}>{String(p.name||"AC").slice(0,2).toUpperCase()}</span><div><strong>{p.name}</strong><span>{p.role||"Participant"} · {p.decision_role||"participant"}</span></div><Badge value={p.confirmation_status}>{p.confirmation_status||"pending"}</Badge></article>)}{!participants.length?<Empty title="Aucun participant" body="Ajoutez les décideurs, influenceurs et membres internes attendus." label="Ajouter depuis le bouton ci-dessus" href={appointmentHref(row)}/>:null}</div></Panel><Panel icon={<FileCheck2 size={17}/>} title="Préparation" subtitle={`${preparation.filter((i:any)=>i.status==="completed").length}/${preparation.length} éléments terminés`} action={<button className={styles.miniButton} onClick={()=>onAction("preparation",row)}><Plus size={14}/>Ajouter</button>}><div className={styles.preparationList}>{preparation.map((item:any)=><article key={item.id}><i data-complete={item.status==="completed"}/><div><strong>{item.title}</strong><span>{item.description||"Aucune instruction"}</span></div><Badge value={item.status}>{item.status||"open"}</Badge></article>)}{!preparation.length?<p className={styles.quietText}>Aucun élément de préparation n’a encore été enregistré.</p>:null}</div></Panel><Panel icon={<MessageSquare size={17}/>} title="Communications" subtitle={`${events.length} interaction(s) enregistrée(s)`} action={<button className={styles.miniButton} onClick={()=>onAction("communication",row)}><Plus size={14}/>Consigner</button>}><div className={styles.timeline}>{events.slice(0,10).map((event:any)=><article key={event.id}><IconBox>{event.channel==="email"?<Mail size={15}/>:event.channel==="phone"?<Phone size={15}/>:event.channel==="whatsapp"?<MessageCircle size={15}/>:<Activity size={15}/>}</IconBox><div><strong>{event.subject||`${event.channel} ${event.direction}`}</strong><p>{event.body_summary||"Interaction enregistrée sans résumé."}</p><span>{dateTime(event.occurred_at)} · {event.owner_name||event.sender}</span></div><Badge value={event.status}>{event.status||"recorded"}</Badge></article>)}{!events.length?<p className={styles.quietText}>Aucune communication liée à ce rendez-vous.</p>:null}</div></Panel></div><aside className={styles.dossierRail}><Panel icon={<CalendarClock size={17}/>} title="État opérationnel"><dl className={styles.facts}><div><dt>Date</dt><dd>{dateTime(row.appointment_at)}</dd></div><div><dt>Confirmation</dt><dd><Badge value={row.confirmation_status}>{row.confirmation_status||"pending"}</Badge></dd></div><div><dt>Préparation</dt><dd>{readiness(row)}%</dd></div><div><dt>Risque absence</dt><dd>{Number(row.no_show_risk||0)}%</dd></div><div><dt>Version</dt><dd>{Number(row.version||0)}</dd></div></dl></Panel><Panel icon={<Handshake size={17}/>} title="Engagements" subtitle={`${commitments.length} engagement(s)`} action={<button className={styles.miniButton} onClick={()=>onAction("commitment",row)}><Plus size={14}/></button>}><div className={styles.compactList}>{commitments.slice(0,6).map((c:any)=><article key={c.id}><strong>{c.title}</strong><span>{c.owner_name||"Non attribué"} · {date(c.due_at)}</span><Badge value={c.status}>{c.status||"open"}</Badge></article>)}{!commitments.length?<p className={styles.quietText}>Aucun engagement enregistré.</p>:null}</div></Panel><Panel icon={<History size={17}/>} title="Historique d’état"><div className={styles.historyList}>{history.slice(0,8).map((h:any)=><article key={h.id}><i/><div><strong>{statusLabel(h.to_status)}</strong><span>{dateTime(h.changed_at||h.created_at)}</span></div></article>)}{!history.length?<p className={styles.quietText}>L’historique se remplira lors des prochaines transitions.</p>:null}</div></Panel><div className={styles.actionStack}><button onClick={()=>onAction("confirm",row)}><UserCheck/>Confirmer</button><button onClick={()=>onAction("reschedule",row)}><RotateCcw/>Replanifier</button><button onClick={()=>onAction("communication",row)}><MessageCircle/>Communication</button><button onClick={()=>onAction("outcome",row)}><Target/>Résultat commercial</button></div></aside></div></div>}

function BriefingExperience({row,portfolio,onAction}:{row?:EngagementAppointment;portfolio:EngagementPortfolio;onAction:(kind:EngagementModalKind,row:EngagementAppointment)=>void}){if(!row)return <Empty title="Briefing indisponible" body="Le rendez-vous demandé ne peut pas être chargé."/>;const participants=portfolio.participants.filter(p=>p.appointment_id===row.id),agenda=portfolio.agendaItems.filter(i=>i.appointment_id===row.id),preparation=portfolio.preparationItems.filter(i=>i.appointment_id===row.id),objections=portfolio.objections.filter(i=>i.appointment_id===row.id);return <div className={styles.briefing}><section className={styles.briefingHeader}><div><Badge value={readiness(row)>=100?"green":"amber"}>Préparation {readiness(row)}%</Badge><h2>{row.title}</h2><p>{relationName(row)} · {dateTime(row.appointment_at)}</p></div><button className={styles.primaryButton} onClick={()=>onAction("preparation",row)}><FileCheck2 size={16}/>Ajouter une préparation</button></section><div className={styles.briefingGrid}><Panel icon={<BriefcaseBusiness size={17}/>} title="Contexte du compte"><div className={styles.briefingContext}><article><span>Relation</span><strong>{relationName(row)}</strong></article><article><span>Contact principal</span><strong>{contactName(row)}</strong></article><article><span>Opportunité</span><strong>{row.opportunity_title||"Non reliée"}</strong></article><article><span>Valeur</span><strong>{dh(row.commercial_value_mad)}</strong></article><p>{row.objective||"Aucun objectif commercial détaillé."}</p></div></Panel><Panel icon={<Users size={17}/>} title="Carte des participants"><div className={styles.peopleGrid}>{participants.map((p:any)=><article key={p.id}><span className={styles.avatar}>{String(p.name||"AC").slice(0,2).toUpperCase()}</span><div><strong>{p.name}</strong><span>{p.decision_role||p.role}</span></div><Badge value={p.confirmation_status}>{p.confirmation_status}</Badge></article>)}</div></Panel><Panel icon={<ListChecks size={17}/>} title="Agenda de réunion" action={<button className={styles.miniButton} onClick={()=>onAction("preparation",row)}><Plus size={14}/></button>}><ol className={styles.agendaList}>{agenda.map((item:any)=><li key={item.id}><span>{Number(item.position||0)+1}</span><div><strong>{item.title}</strong><p>{item.objective||item.description}</p></div><time>{item.duration_minutes||10} min</time></li>)}{!agenda.length?<p className={styles.quietText}>Aucun point d’agenda enregistré.</p>:null}</ol></Panel><Panel icon={<ShieldCheck size={17}/>} title="Checklist de préparation"><div className={styles.preparationList}>{preparation.map((item:any)=><article key={item.id}><i data-complete={item.status==="completed"}/><div><strong>{item.title}</strong><span>{item.owner_name||row.owner}</span></div><Badge value={item.status}>{item.status}</Badge></article>)}</div></Panel><Panel icon={<AlertTriangle size={17}/>} title="Objections anticipées"><div className={styles.objectionList}>{objections.map((item:any)=><article key={item.id}><strong>{item.objection}</strong><p>{item.response||"Réponse à préparer."}</p><Badge value={item.severity}>{item.severity}</Badge></article>)}{!objections.length?<p className={styles.quietText}>Aucune objection n’est encore enregistrée.</p>:null}</div></Panel></div></div>}

function LiveExperience({row,portfolio,onSelect,onAction}:{row?:EngagementAppointment;portfolio:EngagementPortfolio;onSelect:(row:EngagementAppointment)=>void;onAction:(kind:EngagementModalKind,row:EngagementAppointment)=>void}){if(!row){const live=portfolio.appointments.filter(r=>isToday(r.appointment_at)||["prepared","live"].includes(normalize(r.status)));return <div className={styles.liveCommand}><Panel icon={<Mic2 size={17}/>} title="Prêts à démarrer" subtitle="Rendez-vous du jour et dossiers préparés"><div className={styles.liveCards}>{live.map(item=><AppointmentCard key={item.id} row={item} onSelect={onSelect} onAction={onAction}/>)}</div></Panel></div>}const notes=portfolio.notes.filter(n=>n.appointment_id===row.id),objections=portfolio.objections.filter(n=>n.appointment_id===row.id),decisions=portfolio.decisions.filter(n=>n.appointment_id===row.id),commitments=portfolio.commitments.filter(n=>n.appointment_id===row.id),participants=portfolio.participants.filter(n=>n.appointment_id===row.id);return <div className={styles.liveRoom}><header><div><span className={styles.livePulse}><i/>RÉUNION EN DIRECT</span><h2>{row.title}</h2><p>{relationName(row)} · {dateTime(row.appointment_at)}</p></div><div><strong>{time(row.appointment_at)}</strong><Badge value={row.status}>{statusLabel(row.status)}</Badge></div></header><div className={styles.liveLayout}><aside><Panel icon={<Users size={17}/>} title="Participants"><div className={styles.compactPeople}>{participants.map((p:any)=><article key={p.id}><span className={styles.avatar}>{String(p.name||"AC").slice(0,2)}</span><div><strong>{p.name}</strong><span>{p.decision_role||p.role}</span></div><Badge value={p.attendance_status}>{p.attendance_status||"pending"}</Badge></article>)}</div></Panel><Panel icon={<Target size={17}/>} title="Objectif"><p className={styles.liveObjective}>{row.objective||"Objectif non renseigné."}</p></Panel></aside><main><div className={styles.liveToolbar}><button onClick={()=>onAction("note",row)}><FileText/>Note</button><button onClick={()=>onAction("objection",row)}><AlertTriangle/>Objection</button><button onClick={()=>onAction("decision",row)}><BadgeCheck/>Décision</button><button onClick={()=>onAction("commitment",row)}><Handshake/>Engagement</button><button className={styles.primaryButton} onClick={()=>onAction("outcome",row)}><Target/>Clôturer</button></div><Panel icon={<Mic2 size={17}/>} title="Journal de la réunion" subtitle="Capture chronologique"><div className={styles.liveJournal}>{[...notes.map(n=>({...n,kind:"note",label:n.body})),...objections.map(n=>({...n,kind:"objection",label:n.objection})),...decisions.map(n=>({...n,kind:"decision",label:n.decision})),...commitments.map(n=>({...n,kind:"commitment",label:n.title}))].sort((a:any,b:any)=>new Date(a.created_at||a.recorded_at||0).getTime()-new Date(b.created_at||b.recorded_at||0).getTime()).map((item:any)=><article key={`${item.kind}-${item.id}`} data-kind={item.kind}><IconBox>{item.kind==="objection"?<AlertTriangle size={15}/>:item.kind==="decision"?<BadgeCheck size={15}/>:item.kind==="commitment"?<Handshake size={15}/>:<FileText size={15}/>}</IconBox><div><strong>{item.label}</strong><span>{dateTime(item.created_at||item.recorded_at)}</span></div></article>)}{!notes.length&&!objections.length&&!decisions.length&&!commitments.length?<div className={styles.liveBlank}><Mic2 size={28}/><h3>La réunion est prête</h3><p>Ajoutez les notes, objections, décisions et engagements au fil de l’échange.</p></div>:null}</div></Panel></main></div></div>}

function ConversionExperience({portfolio,onSelect,onAction,focused}:{portfolio:EngagementPortfolio;onSelect:(row:EngagementAppointment)=>void;onAction:(kind:EngagementModalKind,row:EngagementAppointment)=>void;focused?:EngagementAppointment}){const rows=focused?[focused]:portfolio.appointments.filter(r=>["live","completed","converted","follow_up"].includes(normalize(r.status)));return <div className={styles.conversionGrid}><Panel icon={<Target size={17}/>} title={focused?"Conclusion du rendez-vous":"File des résultats commerciaux"} subtitle="Décisions, progression et prochaines actions" className={styles.conversionMain}><div className={styles.conversionList}>{rows.map(row=>{const outcome=portfolio.outcomes.find(o=>o.appointment_id===row.id);return <article key={row.id}><div><Badge value={row.status}>{statusLabel(row.status)}</Badge><h3>{row.title}</h3><p>{relationName(row)} · {dh(row.commercial_value_mad)}</p></div><div className={styles.outcomeSummary}><span>Résultat</span><strong>{outcome?.outcome_code||row.outcome_code||"À enregistrer"}</strong><p>{outcome?.summary||row.outcome||"Aucun résultat détaillé."}</p></div><div className={styles.conversionActions}><button onClick={()=>onAction("outcome",row)}><Target/>Enregistrer</button><button onClick={()=>onAction("follow-up",row)}><ArrowRight/>Créer le suivi</button><button onClick={()=>onSelect(row)}><PanelRightOpen/></button></div></article>})}{!rows.length?<Empty title="Aucun résultat en attente" body="Les rendez-vous terminés apparaîtront ici pour conversion."/>:null}</div></Panel><Panel icon={<Handshake size={17}/>} title="Engagements ouverts" subtitle={`${portfolio.summary.openCommitments} suite(s) non clôturée(s)`}><div className={styles.compactList}>{portfolio.commitments.filter(c=>!["completed","cancelled"].includes(c.status)).slice(0,10).map((c:any)=><article key={c.id}><strong>{c.title}</strong><span>{c.owner_name} · {date(c.due_at)}</span><Badge value={c.status}>{c.status}</Badge></article>)}</div></Panel></div>}

function NoShowExperience({portfolio,onSelect,onAction}:{portfolio:EngagementPortfolio;onSelect:(row:EngagementAppointment)=>void;onAction:(kind:EngagementModalKind,row:EngagementAppointment)=>void}){const rows=portfolio.appointments.filter(r=>normalize(r.status)==="no_show"||portfolio.noShows.some(n=>n.appointment_id===r.id));return <Panel icon={<AlertOctagon size={17}/>} title="Non-présentations à traiter" subtitle="Cause, impact et récupération"><div className={styles.recoveryCards}>{rows.map(row=>{const noShow=portfolio.noShows.find(n=>n.appointment_id===row.id);return <article key={row.id}><div className={styles.recoveryIcon}><AlertOctagon/></div><div><Badge value="red">{noShow?.no_show_party==="internal"?"Absence interne":"Absence externe"}</Badge><h3>{row.title}</h3><p>{noShow?.reason||"Motif non détaillé"}</p><span>{relationName(row)} · {dh(noShow?.commercial_impact_mad||row.commercial_value_mad)}</span></div><div><button onClick={()=>onAction("recovery",row)}><RotateCcw/>Récupérer</button><button onClick={()=>onSelect(row)}><ArrowRight/></button></div></article>})}{!rows.length?<Empty title="Aucune non-présentation ouverte" body="Les rendez-vous non honorés apparaîtront ici avec leur impact commercial."/>:null}</div></Panel>}

function RecoveryExperience({portfolio,onSelect,onAction}:{portfolio:EngagementPortfolio;onSelect:(row:EngagementAppointment)=>void;onAction:(kind:EngagementModalKind,row:EngagementAppointment)=>void}){const rows=portfolio.appointments.filter(r=>["no_show","recovery","rescheduled","lost"].includes(normalize(r.status)));return <div className={styles.recoveryGrid}><Panel icon={<RotateCcw size={17}/>} title="Portefeuille de récupération" subtitle="Sauvetage des rendez-vous fragilisés"><div className={styles.recoveryCards}>{rows.map(row=>{const attempts=portfolio.recoveryAttempts.filter(a=>a.appointment_id===row.id);return <article key={row.id}><div className={styles.recoveryIcon}><RotateCcw/></div><div><Badge value={row.status}>{statusLabel(row.status)}</Badge><h3>{row.title}</h3><p>{relationName(row)} · {attempts.length} tentative(s)</p><span>Prochaine action : {attempts[0]?.next_attempt_at?dateTime(attempts[0].next_attempt_at):"À planifier"}</span></div><div><button onClick={()=>onAction("recovery",row)}>Nouvelle tentative</button><button onClick={()=>onSelect(row)}><ArrowRight/></button></div></article>})}{!rows.length?<Empty title="Aucun dossier de récupération" body="La file est actuellement vide."/>:null}</div></Panel><Panel icon={<Phone size={17}/>} title="Canaux utilisés" subtitle="Historique des tentatives"><div className={styles.channelStats}>{["phone","whatsapp","email","meeting"].map(channel=><article key={channel}><span>{channel==="phone"?<Phone/>:channel==="email"?<Mail/>:channel==="whatsapp"?<MessageCircle/>:<Users/>}</span><strong>{portfolio.recoveryAttempts.filter(a=>a.channel===channel).length}</strong><small>{channel}</small></article>)}</div></Panel></div>}

function RescheduleExperience({portfolio,onSelect,onAction}:{portfolio:EngagementPortfolio;onSelect:(row:EngagementAppointment)=>void;onAction:(kind:EngagementModalKind,row:EngagementAppointment)=>void}){const rows=portfolio.appointments.filter(r=>normalize(r.status)==="rescheduled");return <Panel icon={<CalendarClock size={17}/>} title="Replanifications à sécuriser" subtitle="Nouvelle date, reconfirmation et préparation"><div className={styles.rescheduleTimeline}>{rows.map(row=><article key={row.id}><span className={styles.timelineDot}/><div><Badge value="amber">Replanifié</Badge><h3>{row.title}</h3><p>{relationName(row)}</p></div><div><span>Nouvelle date</span><strong>{dateTime(row.appointment_at)}</strong><small>Confirmation : {row.confirmation_status||"pending"}</small></div><div><button onClick={()=>onAction("confirm",row)}>Reconfirmer</button><button onClick={()=>onAction("reschedule",row)}>Modifier</button><button onClick={()=>onSelect(row)}><ArrowRight/></button></div></article>)}{!rows.length?<Empty title="Aucune replanification" body="Les changements de créneau nécessitant une sécurisation apparaîtront ici."/>:null}</div></Panel>}

function RiskExperience({portfolio,onSelect,onAction}:{portfolio:EngagementPortfolio;onSelect:(row:EngagementAppointment)=>void;onAction:(kind:EngagementModalKind,row:EngagementAppointment)=>void}){const rows=portfolio.appointments.filter(r=>Number(r.no_show_risk||0)>=40||normalize(r.status)==="confirmation_pending").sort((a,b)=>Number(b.no_show_risk||0)-Number(a.no_show_risk||0));return <div className={styles.riskWorkspace}><Panel icon={<Radar size={17}/>} title="Carte des risques" subtitle="Risque de non-présentation et défaut de préparation"><div className={styles.riskCards}>{rows.map(row=><article key={row.id} data-level={Number(row.no_show_risk||0)>=70?"critical":Number(row.no_show_risk||0)>=50?"high":"medium"}><header><strong>{Number(row.no_show_risk||0)}%</strong><Badge value={Number(row.no_show_risk||0)>=70?"red":"amber"}>Risque</Badge></header><h3>{row.title}</h3><p>{relationName(row)} · {dateTime(row.appointment_at)}</p><div><span>Confirmation</span><strong>{row.confirmation_status||"pending"}</strong></div><div><span>Préparation</span><strong>{readiness(row)}%</strong></div><footer><button onClick={()=>onAction("confirm",row)}>Confirmer</button><button onClick={()=>onSelect(row)}>Dossier</button></footer></article>)}</div></Panel></div>}

function EscalationExperience({portfolio,onSelect}:{portfolio:EngagementPortfolio;onSelect:(row:EngagementAppointment)=>void}){const rows=portfolio.appointments.filter(r=>Number(r.commercial_value_mad||0)>=25000&&(Number(r.no_show_risk||0)>=50||["no_show","recovery","cancelled"].includes(normalize(r.status))));return <Panel icon={<ShieldAlert size={17}/>} title="Interventions exécutives" subtitle="Valeur stratégique exposée"><div className={styles.escalationList}>{rows.map((row,index)=><article key={row.id}><span className={styles.escalationRank}>{index+1}</span><div><Badge value="red">Décision requise</Badge><h3>{row.title}</h3><p>{relationName(row)} · {dateTime(row.appointment_at)}</p></div><div><span>Valeur exposée</span><strong>{dh(row.commercial_value_mad)}</strong><small>Risque {Number(row.no_show_risk||0)}%</small></div><button onClick={()=>onSelect(row)}>Intervenir<ArrowRight/></button></article>)}{!rows.length?<Empty title="Aucune escalade exécutive" body="Aucun rendez-vous à forte valeur ne nécessite une intervention immédiate."/>:null}</div></Panel>}

function HighValueExperience({portfolio,onSelect,onAction}:{portfolio:EngagementPortfolio;onSelect:(row:EngagementAppointment)=>void;onAction:(kind:EngagementModalKind,row:EngagementAppointment)=>void}){const rows=portfolio.appointments.filter(r=>Number(r.commercial_value_mad||0)>=25000).sort((a,b)=>Number(b.commercial_value_mad||0)-Number(a.commercial_value_mad||0));return <div className={styles.highValueGrid}><section className={styles.valueHero}><span>Portefeuille stratégique</span><strong>{dh(rows.reduce((s,r)=>s+Number(r.commercial_value_mad||0),0))}</strong><p>{rows.length} rendez-vous nécessitent un niveau de préparation renforcé.</p></section><div className={styles.liveCards}>{rows.map(row=><AppointmentCard key={row.id} row={row} onSelect={onSelect} onAction={onAction}/>)}</div></div>}

function AnalyticsExperience({portfolio}:{portfolio:EngagementPortfolio}){const statuses=["scheduled","confirmation_pending","confirmed","prepared","live","completed","converted","no_show"].map(key=>({key,count:portfolio.appointments.filter(r=>normalize(r.status)===key).length}));const channels=["email","whatsapp","phone","meeting","internal"].map(key=>({key,count:portfolio.communicationEvents.filter(e=>e.channel===key).length}));return <div className={styles.analyticsGrid}><Panel icon={<BarChart3 size={17}/>} title="Entonnoir de rendez-vous" subtitle="Volumes par étape"><div className={styles.barChart}>{statuses.map(item=><article key={item.key}><span>{statusLabel(item.key)}</span><div><i style={{width:`${portfolio.summary.total?Math.max(2,item.count/portfolio.summary.total*100):0}%`}}/></div><strong>{item.count}</strong></article>)}</div></Panel><Panel icon={<MessageSquare size={17}/>} title="Mix de communication" subtitle="Événements enregistrés par canal"><div className={styles.channelStats}>{channels.map(item=><article key={item.key}><span>{item.key==="email"?<Mail/>:item.key==="whatsapp"?<MessageCircle/>:item.key==="phone"?<Phone/>:item.key==="meeting"?<Users/>:<FileText/>}</span><strong>{item.count}</strong><small>{item.key}</small></article>)}</div></Panel><Panel icon={<Gauge size={17}/>} title="Indicateurs de qualité" subtitle="Mesures calculées sur les données disponibles"><div className={styles.metricGrid}><article><span>Confirmation</span><strong>{portfolio.summary.confirmedRate}%</strong><Progress value={portfolio.summary.confirmedRate}/></article><article><span>Conversion</span><strong>{portfolio.summary.conversionRate}%</strong><Progress value={portfolio.summary.conversionRate}/></article><article><span>Valeur exposée</span><strong>{dh(portfolio.summary.valueAtRiskMad)}</strong><p>{portfolio.summary.atRisk} dossiers à risque.</p></article><article><span>Engagements ouverts</span><strong>{portfolio.summary.openCommitments}</strong><p>Suites commerciales à clôturer.</p></article></div></Panel></div>}

function PerformanceExperience({portfolio}:{portfolio:EngagementPortfolio}){const owners=Array.from(new Set(portfolio.appointments.map(r=>r.owner||"Non attribué"))).map(owner=>{const rows=portfolio.appointments.filter(r=>(r.owner||"Non attribué")===owner),completed=rows.filter(r=>["completed","converted","follow_up"].includes(normalize(r.status))),converted=rows.filter(r=>normalize(r.status)==="converted"),noShows=rows.filter(r=>normalize(r.status)==="no_show");return{owner,total:rows.length,completed:completed.length,conversion:completed.length?Math.round(converted.length/completed.length*100):0,noShows:noShows.length,value:rows.reduce((s,r)=>s+Number(r.commercial_value_mad||0),0),prepared:rows.filter(r=>readiness(r)===100).length}}).sort((a,b)=>b.value-a.value);return <Panel icon={<Users size={17}/>} title="Performance par responsable" subtitle="Cadence, préparation, conversion et valeur"><div className={styles.performanceTable}>{owners.map((o,index)=><article key={o.owner}><span className={styles.rank}>{String(index+1).padStart(2,"0")}</span><div><strong>{o.owner}</strong><span>{o.total} rendez-vous · {o.prepared} préparés</span></div><div><span>Conversion</span><strong>{o.conversion}%</strong></div><div><span>Absences</span><strong>{o.noShows}</strong></div><div><span>Valeur</span><strong>{dh(o.value)}</strong></div><Progress value={o.total?o.prepared/o.total*100:0}/></article>)}</div></Panel>}

function ExecutiveExperience({portfolio,onSelect}:{portfolio:EngagementPortfolio;onSelect:(row:EngagementAppointment)=>void}){const strategic=[...portfolio.appointments].sort((a,b)=>Number(b.commercial_value_mad||0)-Number(a.commercial_value_mad||0)).slice(0,5);return <div className={styles.executiveGrid}><section className={styles.executiveHero}><div><span>Posture des rencontres</span><strong>{dh(portfolio.summary.commercialValueMad)}</strong><p>Valeur commerciale portée par {portfolio.summary.total} rendez-vous enregistrés.</p></div><div className={styles.executiveMetrics}><article><span>Confirmation</span><strong>{portfolio.summary.confirmedRate}%</strong></article><article><span>Conversion</span><strong>{portfolio.summary.conversionRate}%</strong></article><article><span>Valeur à risque</span><strong>{dh(portfolio.summary.valueAtRiskMad)}</strong></article><article><span>Suites ouvertes</span><strong>{portfolio.summary.openCommitments}</strong></article></div></section><Panel icon={<CircleDollarSign size={17}/>} title="Rencontres stratégiques" subtitle="Plus forte valeur associée"><div className={styles.executiveList}>{strategic.map(row=><button key={row.id} onClick={()=>onSelect(row)}><div><strong>{row.title}</strong><span>{relationName(row)} · {dateTime(row.appointment_at)}</span></div><Badge value={row.status}>{statusLabel(row.status)}</Badge><strong>{dh(row.commercial_value_mad)}</strong><ChevronRight/></button>)}</div></Panel><Panel icon={<ShieldAlert size={17}/>} title="Décisions de direction" subtitle="Priorités calculées à partir des données visibles"><div className={styles.decisionCards}><article><span>01</span><div><strong>Sécuriser les confirmations</strong><p>{portfolio.summary.confirmationPending} rendez-vous attendent une confirmation.</p></div></article><article><span>02</span><div><strong>Finaliser les briefings</strong><p>{portfolio.summary.preparationPending} dossiers confirmés restent incomplets.</p></div></article><article><span>03</span><div><strong>Clôturer les engagements</strong><p>{portfolio.summary.openCommitments} engagements sont encore ouverts.</p></div></article></div></Panel></div>}

function FollowUpExperience({row,portfolio,onAction}:{row?:EngagementAppointment;portfolio:EngagementPortfolio;onAction:(kind:EngagementModalKind,row:EngagementAppointment)=>void}){if(!row)return <Empty title="Rendez-vous introuvable" body="Le plan de suivi demandé n’est pas disponible."/>;const followUps=portfolio.followUps.filter(f=>f.appointment_id===row.id),commitments=portfolio.commitments.filter(c=>c.appointment_id===row.id),tasks=portfolio.tasks.filter(t=>t.entity_id===row.id);return <div className={styles.followUpGrid}><Panel icon={<ArrowRight size={17}/>} title="Plan de suivi" subtitle={`${followUps.length} action(s) structurée(s)`} action={<button className={styles.miniButton} onClick={()=>onAction("follow-up",row)}><Plus/>Ajouter</button>}><div className={styles.followUpTimeline}>{followUps.map((f:any)=><article key={f.id}><span className={styles.timelineDot}/><div><Badge value={f.status}>{f.status}</Badge><h3>{f.title}</h3><p>{f.description||"Aucune instruction"}</p></div><div><strong>{f.owner_name||row.owner}</strong><span>{dateTime(f.due_at)}</span></div></article>)}{!followUps.length?<Empty title="Aucun suivi structuré" body="Créez la prochaine action commerciale issue du rendez-vous." label="Ajouter depuis le bouton ci-dessus" href={appointmentHref(row)}/>:null}</div></Panel><div><Panel icon={<Handshake size={17}/>} title="Engagements"><div className={styles.compactList}>{commitments.map((c:any)=><article key={c.id}><strong>{c.title}</strong><span>{c.owner_name} · {date(c.due_at)}</span><Badge value={c.status}>{c.status}</Badge></article>)}</div></Panel><Panel icon={<Workflow size={17}/>} title="Tâches générées"><div className={styles.compactList}>{tasks.map((t:any)=><article key={t.id}><strong>{t.title}</strong><span>{t.owner} · {date(t.due_at||t.due_date)}</span><Badge value={t.status}>{t.status}</Badge></article>)}</div></Panel></div></div>}

function AppointmentDrawer({row,onClose,onAction}:{row:EngagementAppointment;onClose:()=>void;onAction:(kind:EngagementModalKind,row:EngagementAppointment)=>void}){return <div className={styles.drawerBackdrop} onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><aside className={styles.drawer}><header><div><Badge value={row.status}>{statusLabel(row.status)}</Badge><h2>{row.title}</h2><p>{relationName(row)}</p></div><button onClick={onClose} aria-label="Fermer"><X/></button></header><div className={styles.drawerBody}><div className={styles.drawerDate}><CalendarDays/><div><strong>{dateTime(row.appointment_at)}</strong><span>{row.location||row.meeting_link||"Lieu à confirmer"}</span></div></div><dl><div><dt>Contact</dt><dd>{contactName(row)}</dd></div><div><dt>Responsable</dt><dd>{row.owner||"Non attribué"}</dd></div><div><dt>Valeur</dt><dd>{dh(row.commercial_value_mad)}</dd></div><div><dt>Risque</dt><dd>{Number(row.no_show_risk||0)}%</dd></div></dl><section><h3>Objectif</h3><p>{row.objective||"Non renseigné."}</p></section><Progress value={readiness(row)} label="Préparation"/><div className={styles.drawerSignals}><span><Users/>{row.participant_count||0} participants</span><span><MessageSquare/>{row.communication_count||0} interactions</span><span><Handshake/>{row.open_commitment_count||0} engagements</span></div></div><footer><button onClick={()=>onAction("communication",row)}><MessageCircle/>Interaction</button><Link href={appointmentHref(row)} className={styles.primaryButton}>Dossier complet<ArrowRight/></Link></footer></aside></div>}

const MODAL_COPY:Record<EngagementModalKind,{title:string;description:string;icon:React.ReactNode}>={
  schedule:{title:"Planifier un rendez-vous",description:"Créer un engagement daté et relié à un dossier commercial.",icon:<CalendarCheck2/>},participant:{title:"Ajouter un participant",description:"Identifier le rôle, l’influence et la confirmation attendue.",icon:<Users/>},confirm:{title:"Enregistrer une confirmation",description:"Conserver le canal et la décision de présence.",icon:<UserCheck/>},reschedule:{title:"Replanifier le rendez-vous",description:"Définir le nouveau créneau et imposer une reconfirmation.",icon:<RotateCcw/>},cancel:{title:"Annuler le rendez-vous",description:"Motiver la décision et préserver la trace commerciale.",icon:<X/>},communication:{title:"Consigner une interaction",description:"Enregistrer un email, WhatsApp, appel ou échange interne sans simuler l’envoi.",icon:<MessageCircle/>},"follow-up":{title:"Créer un suivi",description:"Transformer une conclusion en action datée et assignée.",icon:<ArrowRight/>},"no-show":{title:"Déclarer une non-présentation",description:"Qualifier la cause, l’impact et le besoin de récupération.",icon:<AlertOctagon/>},recovery:{title:"Lancer une récupération",description:"Consigner une tentative et, si possible, un nouveau créneau.",icon:<RotateCcw/>},preparation:{title:"Ajouter un élément de préparation",description:"Structurer briefing, document, agenda ou question critique.",icon:<FileCheck2/>},note:{title:"Ajouter une note en direct",description:"Capturer un fait, une précision ou une observation horodatée.",icon:<FileText/>},objection:{title:"Enregistrer une objection",description:"Qualifier l’objection et préparer ou consigner la réponse.",icon:<AlertTriangle/>},decision:{title:"Enregistrer une décision",description:"Conserver la décision, son auteur et son impact commercial.",icon:<BadgeCheck/>},commitment:{title:"Ajouter un engagement",description:"Attribuer une responsabilité et une échéance vérifiable.",icon:<Handshake/>},outcome:{title:"Clôturer avec un résultat commercial",description:"Propager le résultat vers les suivis, tâches et opportunités autorisées.",icon:<Target/>},
}

function EngagementModal({kind,row,onClose,onSaved}:{kind:EngagementModalKind;row?:EngagementAppointment;onClose:()=>void;onSaved:()=>void}){const config=MODAL_COPY[kind],dialogRef=useRef<HTMLFormElement|null>(null),previousFocus=useRef<HTMLElement|null>(null);const [primary,setPrimary]=useState(""),[secondary,setSecondary]=useState(""),[dateValue,setDateValue]=useState(""),[selectValue,setSelectValue]=useState(kind==="communication"?"phone":kind==="outcome"?"follow_up":"medium"),[amount,setAmount]=useState("0"),[busy,setBusy]=useState(false),[error,setError]=useState<string|null>(null);useEffect(()=>{previousFocus.current=document.activeElement as HTMLElement;document.body.style.overflow="hidden";const first=dialogRef.current?.querySelector<HTMLElement>("input,select,textarea,button");first?.focus();function key(e:KeyboardEvent){if(e.key==="Escape")onClose();if(e.key==="Tab"&&dialogRef.current){const focusable=Array.from(dialogRef.current.querySelectorAll<HTMLElement>('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),a[href]'));if(!focusable.length)return;const first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}}window.addEventListener("keydown",key);return()=>{document.body.style.overflow="";window.removeEventListener("keydown",key);previousFocus.current?.focus()}},[onClose]);async function submit(e:React.FormEvent){e.preventDefault();if(!row&&kind!=="schedule")return;setBusy(true);setError(null);try{const common={appointmentId:row?.id};if(kind==="participant")await engagementMutation("/api/revenue-command-center/engagement/participants",{...common,name:primary,role:secondary,decisionRole:selectValue,email:"",isRequired:true});if(kind==="confirm")await engagementMutation("/api/revenue-command-center/engagement/confirmations",{...common,status:"confirmed",channel:selectValue,note:secondary});if(kind==="reschedule")await engagementMutation(`/api/revenue-command-center/engagement/appointments/${row?.id}/transition`,{toStatus:"rescheduled",appointmentAt:dateValue,reason:secondary||primary,expectedVersion:row?.version||0});if(kind==="cancel")await engagementMutation(`/api/revenue-command-center/engagement/appointments/${row?.id}/transition`,{toStatus:"cancelled",reason:primary,expectedVersion:row?.version||0});if(kind==="communication")await engagementMutation("/api/revenue-command-center/engagement/communications/events",{...common,prospectId:row?.prospect_id,accountId:row?.account_id,contactId:row?.contact_id,opportunityId:row?.opportunity_id,channel:selectValue,direction:"outbound",subject:primary,bodySummary:secondary,followUpAt:dateValue,status:"recorded"});if(kind==="follow-up")await engagementMutation("/api/revenue-command-center/engagement/follow-ups",{...common,title:primary,description:secondary,dueAt:dateValue,channel:selectValue,createTask:true});if(kind==="no-show")await engagementMutation("/api/revenue-command-center/engagement/no-shows",{...common,reason:primary,category:selectValue,commercialImpactMad:Number(amount),recoveryRequired:true});if(kind==="recovery")await engagementMutation("/api/revenue-command-center/engagement/recovery",{...common,channel:selectValue,outcome:primary,notes:secondary,newAppointmentAt:dateValue,status:"attempted"});if(kind==="preparation")await engagementMutation("/api/revenue-command-center/engagement/preparation",{...common,title:primary,description:secondary,kind:selectValue,status:"open"});if(kind==="note")await engagementMutation("/api/revenue-command-center/engagement/notes",{...common,body:primary,noteType:selectValue});if(kind==="objection")await engagementMutation("/api/revenue-command-center/engagement/objections",{...common,objection:primary,response:secondary,category:selectValue,severity:"medium"});if(kind==="decision")await engagementMutation("/api/revenue-command-center/engagement/decisions",{...common,decision:primary,businessImpact:secondary,decisionType:selectValue});if(kind==="commitment")await engagementMutation("/api/revenue-command-center/engagement/commitments",{...common,title:primary,description:secondary,dueAt:dateValue,ownerName:selectValue||row?.owner,createTask:true});if(kind==="outcome")await engagementMutation("/api/revenue-command-center/engagement/outcomes",{...common,summary:primary,outcomeCode:selectValue,followUpObjective:secondary,followUpAt:dateValue,commercialValueMad:Number(amount||row?.commercial_value_mad||0),followUpRequired:selectValue!=="lost",proposalRequired:selectValue==="proposal_required",applyOpportunity:false});onSaved();onClose()}catch(cause){setError(cause instanceof Error?cause.message:"Action impossible")}finally{setBusy(false)}}const selectOptions=kind==="communication"?[["phone","Appel"],["whatsapp","WhatsApp"],["email","Email"],["internal","Note interne"]]:kind==="confirm"?[["phone","Téléphone"],["whatsapp","WhatsApp"],["email","Email"],["manual","Confirmation directe"]]:kind==="preparation"?[["preparation","Préparation"],["agenda","Point d’agenda"]]:kind==="outcome"?[["follow_up","Suivi requis"],["converted","Converti"],["proposal_required","Proposition requise"],["completed","Terminé"],["lost","Perdu"]]:kind==="recovery"?[["phone","Téléphone"],["whatsapp","WhatsApp"],["email","Email"],["meeting","Nouvelle rencontre"]]:kind==="no-show"?[["unconfirmed","Non confirmé"],["late_cancel","Annulation tardive"],["technical","Incident technique"],["unknown","Cause inconnue"]]:kind==="objection"?[["commercial","Commerciale"],["price","Prix"],["trust","Confiance"],["timing","Calendrier"],["scope","Périmètre"]]:kind==="decision"?[["commercial","Commerciale"],["operational","Opérationnelle"],["financial","Financière"],["next_step","Prochaine étape"]]:kind==="note"?[["live","Note en direct"],["fact","Fait confirmé"],["question","Question"],["private","Note interne"]]:[];return <div className={styles.dialogBackdrop} onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><form ref={dialogRef} className={styles.dialog} role="dialog" aria-modal="true" aria-labelledby="engagement-dialog-title" onSubmit={submit}><header><div><IconBox>{config.icon}</IconBox><div><h2 id="engagement-dialog-title">{config.title}</h2><p>{config.description}</p></div></div><button type="button" onClick={onClose} aria-label="Fermer"><X/></button></header><div className={styles.dialogBody}>{selectOptions.length?<label><span>Type / canal</span><select value={selectValue} onChange={e=>setSelectValue(e.target.value)}>{selectOptions.map(([value,label])=><option key={value} value={value}>{label}</option>)}</select></label>:null}<label><span>{kind==="participant"?"Nom du participant":kind==="communication"?"Objet":kind==="outcome"?"Résumé du résultat":kind==="no-show"?"Motif":kind==="recovery"?"Résultat de la tentative":kind==="note"?"Note":kind==="objection"?"Objection":kind==="decision"?"Décision":kind==="commitment"?"Engagement":"Intitulé / motif"}</span>{["outcome","note","objection"].includes(kind)?<textarea rows={5} value={primary} onChange={e=>setPrimary(e.target.value)} required/>:<input value={primary} onChange={e=>setPrimary(e.target.value)} required/>}</label>{!["cancel","no-show","note"].includes(kind)?<label><span>{kind==="participant"?"Rôle":kind==="communication"?"Résumé de l’échange":kind==="outcome"?"Objectif du suivi":kind==="objection"?"Réponse / traitement":kind==="decision"?"Impact commercial":"Contexte et instruction"}</span><textarea rows={4} value={secondary} onChange={e=>setSecondary(e.target.value)}/></label>:null}{["reschedule","communication","follow-up","recovery","commitment","outcome"].includes(kind)?<label><span>{kind==="reschedule"||kind==="recovery"?"Nouveau créneau":"Échéance / suivi"}</span><input type="datetime-local" value={dateValue} onChange={e=>setDateValue(e.target.value)} required={kind==="reschedule"}/></label>:null}{["no-show","outcome"].includes(kind)?<label><span>Valeur commerciale concernée (Dh)</span><input type="number" min="0" value={amount} onChange={e=>setAmount(e.target.value)}/></label>:null}{error?<div className={styles.formError}><AlertTriangle/>{error}</div>:null}</div><footer><button type="button" className={styles.secondaryButton} onClick={onClose}>Annuler</button><button className={styles.primaryButton} disabled={busy}>{busy?<Loader2 className={styles.spin}/>:<Check/>}Confirmer l’action</button></footer></form></div>}

export default function RevenueEngagementWorkspace({experience}:{experience:EngagementExperienceKey}){const params=useParams(),appointmentId=typeof params?.id==="string"?params.id:null,contract=ENGAGEMENT_ROUTE_CONTRACTS[experience],{data,loading,error,refresh}=useEngagementPortfolio(experience,appointmentId),[selected,setSelected]=useState<EngagementAppointment|null>(null),[modal,setModal]=useState<{kind:EngagementModalKind;row?:EngagementAppointment}|null>(null),[search,setSearch]=useState(""),[status,setStatus]=useState("all");const filtered=useMemo(()=>data.appointments.filter(row=>(status==="all"||normalize(row.status)===status)&&(!search||`${row.title} ${relationName(row)} ${contactName(row)} ${row.owner}`.toLowerCase().includes(search.toLowerCase()))),[data.appointments,search,status]);const portfolio={...data,appointments:filtered},focused=appointmentId?data.appointments.find(row=>row.id===appointmentId):undefined;function open(kind:EngagementModalKind,row?:EngagementAppointment){setModal({kind,row})}let content:React.ReactNode;if(loading)content=<div className={styles.loading}><Loader2 className={styles.spin}/><strong>Synchronisation du control plane d’engagement…</strong><span>Lecture des rendez-vous, participants, communications, décisions et suites.</span></div>;else if(error)content=<div className={styles.errorState}><AlertTriangle/><h2>Le portefeuille d’engagement est indisponible</h2><p>{error}</p><button className={styles.primaryButton} onClick={refresh}><RefreshCcw/>Réessayer</button></div>;else if(contract.archetype==="studio")content=<ScheduleStudio experience={experience} onCreated={refresh}/>;else if(contract.archetype==="dossier")content=<DossierExperience row={focused} portfolio={data} onAction={open}/>;else if(contract.archetype==="briefing")content=<BriefingExperience row={focused} portfolio={data} onAction={open}/>;else if(contract.archetype==="live")content=<LiveExperience row={focused} portfolio={portfolio} onSelect={setSelected} onAction={open}/>;else if(contract.archetype==="conversion")content=<ConversionExperience portfolio={portfolio} focused={focused} onSelect={setSelected} onAction={open}/>;else if(contract.archetype==="calendar")content=<CalendarExperience portfolio={portfolio} onSelect={setSelected}/>;else if(contract.archetype==="queue")content=<QueueExperience portfolio={portfolio} onSelect={setSelected} onAction={open}/>;else if(contract.archetype==="control")content=<ControlTowerExperience portfolio={portfolio} onSelect={setSelected} onAction={open}/>;else if(contract.archetype==="dashboard")content=<DashboardExperience portfolio={portfolio} onSelect={setSelected}/>;else if(contract.archetype==="no-shows")content=<NoShowExperience portfolio={portfolio} onSelect={setSelected} onAction={open}/>;else if(contract.archetype==="recovery")content=<RecoveryExperience portfolio={portfolio} onSelect={setSelected} onAction={open}/>;else if(contract.archetype==="reschedules")content=<RescheduleExperience portfolio={portfolio} onSelect={setSelected} onAction={open}/>;else if(contract.archetype==="risk")content=<RiskExperience portfolio={portfolio} onSelect={setSelected} onAction={open}/>;else if(contract.archetype==="escalations")content=<EscalationExperience portfolio={portfolio} onSelect={setSelected}/>;else if(contract.archetype==="high-value")content=<HighValueExperience portfolio={portfolio} onSelect={setSelected} onAction={open}/>;else if(contract.archetype==="analytics")content=<AnalyticsExperience portfolio={portfolio}/>;else if(contract.archetype==="performance")content=<PerformanceExperience portfolio={portfolio}/>;else if(contract.archetype==="executive")content=<ExecutiveExperience portfolio={portfolio} onSelect={setSelected}/>;else if(contract.archetype==="follow-up")content=<FollowUpExperience row={focused} portfolio={data} onAction={open}/>;else content=<CommandExperience portfolio={portfolio} onSelect={setSelected} onAction={open}/>;return <main className={styles.workspace} data-accent={contract.accent} data-experience={experience}><header className={styles.hero}><div className={styles.heroTop}><div><span className={styles.eyebrow}><i/>ANGELCARE REVENUE COMMAND · {contract.eyebrow}</span><h1>{contract.title}</h1><p>{contract.mission}</p></div><div className={styles.heroActions}>{contract.primaryHref?<Link href={contract.primaryHref} className={styles.primaryButton}><Plus/>{contract.primaryAction}</Link>:focused?<button className={styles.primaryButton} onClick={()=>open(contract.archetype==="live"?"outcome":contract.archetype==="follow-up"?"follow-up":"communication",focused)}><Plus/>{contract.primaryAction}</button>:<button className={styles.primaryButton} onClick={()=>refresh()}><RefreshCcw/>{contract.primaryAction}</button>}<button className={styles.secondaryButton} onClick={refresh}><RefreshCcw/>Actualiser</button></div></div><div className={styles.trustBar}><span><ShieldCheck/>Permissions serveur appliquées</span><span><Activity/>Interactions persistées</span><span><Users/>Participants reliés</span><span><Clock3/>Synchronisé {dateTime(data.syncedAt)}</span></div></header><nav className={styles.subnav}>{ENGAGEMENT_NAVIGATION.map(([label,href])=><Link key={href} href={href} data-active={(experience==="engagement-command"&&href.endsWith("appointments"))||(experience==="queue"&&href.endsWith("queue"))||(experience==="calendar"&&href.endsWith("calendar"))||(experience==="control-tower"&&href.endsWith("control-tower"))||(["live-command","live-room"].includes(experience)&&href.endsWith("live"))||(["conversion","outcome-studio","follow-up"].includes(experience)&&href.endsWith("conversion"))||(experience==="no-shows"&&href.endsWith("no-shows"))||(experience==="analytics"&&href.endsWith("analytics"))?"true":"false"}>{label}</Link>)}</nav>{!loading&&!error&&!appointmentId&&contract.archetype!=="studio"?<><KpiStrip portfolio={data}/><div className={styles.controlBar}><label><Search/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Rechercher rendez-vous, compte, contact ou responsable…"/></label><select value={status} onChange={e=>setStatus(e.target.value)}><option value="all">Tous les états</option><option value="scheduled">Planifiés</option><option value="confirmation_pending">Confirmation attendue</option><option value="confirmed">Confirmés</option><option value="prepared">Préparés</option><option value="live">En direct</option><option value="completed">Terminés</option><option value="converted">Convertis</option><option value="no_show">Non honorés</option><option value="recovery">Récupération</option></select><span><Filter/>{filtered.length} résultat(s)</span></div></>:null}<div className={styles.content}>{content}</div>{selected?<AppointmentDrawer row={selected} onClose={()=>setSelected(null)} onAction={open}/>:null}{modal?<EngagementModal kind={modal.kind} row={modal.row} onClose={()=>setModal(null)} onSaved={refresh}/>:null}</main>}
